const current = $('Store Info').first().json.checksum;
const stored = $input.first().json?.result?.points?.[0]?.payload?.checksum;

return [{ json: { needsUpdate: current !== stored } }];

// AUCUNE MÉTADONNÉE - juste le texte !
const items = [];

for (const item of $input.all()) {
  const row = item.json;
  let text = '';

  for (const [key, value] of Object.entries(row)) {
    if (value && value !== '') {
      text += `${key}: ${value}. `;
    }
  }

  if (text.trim()) {
    items.push({
      json: {
        data: { text: text.trim() }
        // PAS de metadata du tout !
      }
    });
  }
}

return items;

// UN SEUL document avec le checksum pour comparaison future
return [{
  json: {
    data: { text: 'checksum' },
    checksum: $('Store Info').first().json.checksum
  }
}];

// Récupérer les données depuis l'input
const items = $input.all();
const aiOutput = items[0].json.output;
const userRequest = items[0].json.userRequest;

// Fonction pour extraire le genre musical
function extractMusicGenre(text) {
  const genres = [
    {keyword: "tech house", name: "Tech-House"},
    {keyword: "deep house", name: "Deep-House"},
    {keyword: "afro house", name: "Afro-House"},
    {keyword: "progressive house", name: "Progressive-House"},
    {keyword: "house", name: "House"},
    {keyword: "techno", name: "Techno"},
    {keyword: "trance", name: "Trance"},
    {keyword: "afrobeat", name: "Afrobeat"}
  ];

  const lower = text.toLowerCase();

  for (const genre of genres) {
    if (lower.includes(genre.keyword)) {
      return `Playlist-${genre.name}`;
    }
  }

  return "Playlist-Mix";
}

const cleanFileName = extractMusicGenre(userRequest);
const filename = `${cleanFileName}.txt`;

// Extraire les lignes numérotées
const lines = aiOutput.split('\n');
const trackLines = lines.filter(line => /^\d+\./.test(line));
const cleanTracks = trackLines.map(line => {
  return line.replace(/^\d+\.\s*/, '').trim();
});

const content = cleanTracks.join('\n');

// Créer le header
const now = new Date();
const dateStr = now.toLocaleDateString('fr-FR') + ' ' + now.toLocaleTimeString('fr-FR');
const header = `🎵 PLAYLIST DJ - ${cleanFileName.replace('Playlist-', '')}\n`
  + `📅 Généré le : ${dateStr}\n`
  + `🎧 Nombre de titres : ${cleanTracks.length}\n`
  + `${'='.repeat(60)}\n\n`;

const finalContent = header + content;
const finalBuffer = Buffer.from(finalContent, 'utf8');

return {
  json: {
    filename: filename,
    trackCount: cleanTracks.length,
    genre: cleanFileName.replace('Playlist-', '')
  },
  binary: {
    data: {
      data: finalBuffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: filename,
      fileSize: finalBuffer.length
    }
  }
};

// Récupérer la sortie de l'AI Agent
const aiOutput = $input.item.json.output;

// Compter le nombre de lignes qui commencent par un numéro
const lines = aiOutput.split('\n');
const trackLines = lines.filter(line => line.match(/^\d+\./));
const trackCount = trackLines.length;

return {
  json: {
    output: aiOutput,
    trackCount: trackCount,
    isValid: trackCount === 20,
    validationMessage: trackCount === 20 
      ? '✅ Playlist valide avec 20 titres' 
      : `⚠️ Nombre incorrect de titres : ${trackCount}/20`
  }
};

